INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64188022', 64188022, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Content Strategist Komunikasi dan Pemasaran Februari 1 #1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 10175000, 'January 2026', 'APBD', 1, 1, '1 orang x 1 bulan', '1. Membuat strategi komunikasi, target audiens, pesan utama, tema konten, hingga creative brief untuk seluruh kanal publikasi Jakarta Smart City; 2. Mengarahkan ide dan konsep kreatif untuk materi visual, audio-visual, media luar ruang, serta media elektronik sesuai standar brand; 3. Menyusun dan mengelola kalender editorial konten secara rutin, sekaligus memastikan sinkronisasi dengan kampanye yang berlangsung; 4. Memantau tren, isu strategis, dan percakapan publik di media sosial maupun media massa untuk mengidentifikasi peluang konten guna mencapai target media sosial Jakarta Smart City; 5. Menyusun laporan berkala terkait performa konten, efektivitas strategi, dan rekomendasi pengembangan berdasarkan data; dan 6. Berkoordinasi dengan tim internal dan mitra, serta memastikan konsistensi brand voice Jakarta Smart City dalam seluruh konten.', 'Tenaga Ahli Tidak Ber SKA / SKK Spesifikasi: S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1422233);
